sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var {
        name,
        payload
    } = event;  
    if (name === 'NOW_TYPEAHEAD#SELECTED_ITEM_SET') {
        if (event.elementId == 'source_table') {
            if (payload.value) {
                api.setState('sourceTable', payload.item.label);
                api.setState('sourceTableId', payload.value);
                //Clear the supporting data fields when table is changed
                if (api.state.sourceTableId && api.state.sourceTableId != payload.value)
                    api.setState('supportingDataFields', []);
            }
        }
    }
    //Searching tables based on initials
    if (name === "NOW_TYPEAHEAD#VALUE_SET") {
        api.setState('tableSearchString', payload.value);
        //Clear the supporting data fields when table is changed
        if (api.state.sourceTable && api.state.sourceTable != payload.value)
            api.setState('supportingDataFields', []);
    }
}
